import sqlite3, json
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("sqlite", sqlite3.sqlite_version)
try:
    print("json_each ok:", con.execute("SELECT COUNT(*) FROM json_each('[\"a\",\"b\"]')").fetchone())
except Exception as e: print("json_each FAIL", e)
for r in con.execute("SELECT slug, local_ref_id, global_ref_id, substr(connections_produced,1,400), length(connections_produced) FROM citation_mining WHERE created_by_session LIKE '%batch-05%'"):
    print(r)
print("--- containment derivation (mining connections that are admitted sources on the same slug)")
q = """
SELECT m.global_ref_id AS container, es.ref_id AS contained, m.slug, j.value AS doi
FROM citation_mining m, json_each(m.connections_produced) j
JOIN evidence_sources es ON lower(es.doi) = lower(j.value)
JOIN source_slug_links l ON l.ref_id = es.ref_id AND l.slug = m.slug
WHERE COALESCE(m.deferred_reason,'')='' AND es.ref_id <> m.global_ref_id
"""
for r in con.execute(q): print(r)
print("--- evidence_sources DOIs")
for r in con.execute("SELECT ref_id, doi, pmcid, pmid, url, substr(pub_title,1,60) FROM evidence_sources"): print(r)
print("--- terms_used batch05")
for r in con.execute("SELECT exec_id, terms_used IS NOT NULL AND terms_used<>'' , substr(terms_used,1,80) FROM search_executions WHERE exec_id>=29"): print(r)
print("--- FKs onto evidence_sources.ref_id")
n=0
for t in [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")]:
    for fk in con.execute(f"PRAGMA foreign_key_list('{t}')"):
        if fk[2]=='evidence_sources': n+=1; print("  ",t, fk[3])
print("count", n)
print("--- serves_axes")
print(con.execute("SELECT slug, serves_axes FROM slugs WHERE serves_axes IS NOT NULL AND serves_axes<>''").fetchall())
print("--- D-0157 full")
for r in con.execute("SELECT rationale, outcome, notes FROM decisions WHERE decision_id='D-0157'"): print(r[0]); print('OUTCOME:', r[1]); print('NOTES:', r[2])
